def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); comp=[]
          while q:
            x,y=q.pop(); comp.append((x,y))
            for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
              if 0<=nx<h and 0<=ny<w and grid[nx][ny] and (nx,ny) not in seen:
                seen.add((nx,ny)); q.append((nx,ny))
          comps.append(comp)
    comp=max(comps,key=len)
    r0=min(r for r,c in comp); r1=max(r for r,c in comp); c0=min(c for r,c in comp); c1=max(c for r,c in comp)
    a=[row[c0:c1+1] for row in grid[r0:r1+1]]; H,W=len(a),len(a[0])
    return [[a[H-1-r][W-1-c] for r in range(H)] for c in range(W)]
